import"./chunk-2NFLSA4Y.js";var a={interference:{theory:{concept:"[[Interference is the overlapping of two or more coherent waves \u2014 waves with the same frequency and a constant phase difference \u2014 in which they strengthen each other at some points and weaken or cancel each other at others.]] By the superposition principle the displacements of overlapping waves add: y = y\u2081 + y\u2082. If the waves arrive in phase (crest with crest), their amplitudes add \u2014 constructive interference; if they arrive in antiphase (crest with trough), their amplitudes subtract \u2014 destructive interference. In general, the resulting amplitude depends on the phase difference \u03C6."},section:{combine:{title:"Waves add together",text:"At every point in the medium, the combined displacement is the sum of the displacements caused by each wave. The two component waves continue travelling through one another; after they pass, each carries on unchanged."},constructive:{title:"Constructive interference",text:"When two crests arrive together, or two troughs arrive together, their displacements add. For equal waves in phase, the combined amplitude is twice either wave's amplitude. A phase difference of 0\xB0 gives this strongest reinforcement."},destructive:{title:"Destructive interference",text:"When a crest meets a trough, one displacement subtracts from the other. Equal waves exactly out of phase (180\xB0) cancel everywhere, making a flat resultant even though both component waves still exist. If their amplitudes differ, the larger wave is only partly cancelled."},phase:{title:"Phase difference",text:"[[Phase tells where a wave is in its cycle.]] A phase difference of 90\xB0 means a quarter-cycle offset; 180\xB0 means half a cycle. For two waves of the same frequency travelling together, the phase difference sets the resultant amplitude at every point."},energy:{title:"Where the energy goes",text:"[[Cancellation does not destroy energy.]] In a real interference pattern, energy is redistributed: places with weaker waves are balanced by places with stronger waves. This simulation shows displacement, not a detailed energy-flow model."},check:{title:"Check your understanding",text:"What phase difference doubles the amplitude of two equal waves? (0\xB0.) What phase difference cancels them? (180\xB0.) If the waves have different amplitudes, can they cancel completely? (No; the remainder has the difference between their amplitudes.) Change the controls to check each answer."}},formula:{superposition:"Superposition: the resultant displacement is the sum of the two waves",wavelength:"Wavelength equals wave speed divided by frequency",amplitude:"Resultant amplitude for two waves with phase difference \u03C6",limits:"Resultant amplitude for in-phase and opposite-phase waves"},variable:{components:"Displacements of wave 1 and wave 2",result:"Combined displacement",amplitudes:"Amplitudes of the two component waves"},assumption:{coherent:"Both waves have the same frequency and speed, so their phase difference stays constant as they travel.",linear:"The medium is linear: waves pass through one another and their displacements add without changing either wave.",drawing:"The curves show displacement against position on one shared axis; this is a simplified one-dimensional picture, not a drawing of a particular string or room."},param:{frequency:"Frequency of both waves",amplitude1:"Amplitude of wave 1",amplitude2:"Amplitude of wave 2",phase:"Phase difference",speed:"Wave speed",timeStep:"Time step"},hint:{frequency:"Both waves have the same frequency, so they stay in step with a fixed phase difference.",amplitude:"The height of a wave from its middle line to a crest.",phase:"Change how far wave 2 is shifted through its cycle relative to wave 1.",speed:"The speed at which both waves travel through the medium."},preset:{slow:"Slow",normal:"Normal",fast:"Fast",inPhase:"In phase \xB7 0\xB0",quarterPhase:"Quarter-cycle \xB7 90\xB0",opposite:"Opposite \xB7 180\xB0"},measure:{resultantAmplitude:"Resultant amplitude",wavelength:"Wavelength",period:"Period",probeTotal:"Combined displacement at the probe",probe1:"Wave 1 displacement at the probe",probe2:"Wave 2 displacement at the probe"},graph:{displacement:"Wave displacements at the probe over time"},view:{wavesOption:"Show component waves and their sum",probeOption:"Show the marked probe",wave1:"Wave 1",wave2:"Wave 2 \xB7 phase {phase}",total:"Combined wave",probe:"Combined displacement: {value}",wavelength:"\u03BB = {value}",position:"Position x (m)"},challenge:{double:{title:"Double the wave",description:"Make two waves combine to an amplitude of 1.00 m.",hint:"Use equal 0.50 m waves with a phase difference of 0\xB0."},cancel:{title:"Make them cancel",description:"Make the combined wave's amplitude no more than 0.02 m.",hint:"Use equal amplitudes and set the phase difference to 180\xB0."},unequal:{title:"Leave a remainder",description:"Use unequal amplitudes in opposite phase and make the resultant amplitude equal their difference.",hint:"At 180\xB0, subtract the smaller wave's amplitude from the larger one."},quarter:{title:"Offset by a quarter-cycle",description:"Set the phase difference to 90\xB0 and make the combined amplitude greater than 0.50 m.",hint:"Equal waves offset by 90\xB0 still reinforce partly."},wavelength:{title:"Set a 2 m wavelength",description:"Adjust frequency and wave speed until the wavelength is 2 m.",hint:"Wavelength is wave speed divided by frequency."}}}},i={sim:a};export{i as default,a as sim};
